[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ScreenVault — UI & UX Design Inspiration for Mobile & Web Apps</title>
  <meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary-dark: #141414;
      --bg-white: #FFFFFF;
      --surface-gray: #F5F5F5;
      --text-secondary: #6B7280;
      --text-tertiary: #9CA3AF;
      --border-color: #E5E7EB;
      --accent: #6C5CE7;
      --accent-hover: #5A4BD1;
      --accent-light: #EDE9FF;
      --radius: 12px;
      --radius-sm: 8px;
      --radius-pill: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
      --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--primary-dark);
      background: var(--bg-white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== ANNOUNCEMENT BAR ===== */
    .announcement-bar {
      background: var(--primary-dark);
      color: white;
      text-align: center;
      padding: 10px 24px;
      font-size: 13px;
      font-weight: 500;
      letter-spacing: 0.02em;
    }
    .announcement-bar a {
      color: #A78BFA;
      text-decoration: none;
      margin-left: 6px;
    }
    .announcement-bar a:hover { text-decoration: underline; }

    /* ===== HEADER / NAV ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-color);
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }
    .logo {
      font-size: 20px;
      font-weight: 800;
      color: var(--primary-dark);
      text-decoration: none;
      letter-spacing: -0.02em;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .logo-icon {
      width: 32px;
      height: 32px;
      background: var(--accent);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 18px; height: 18px; }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      transition: color var(--transition);
    }
    .nav-links a:hover { color: var(--primary-dark); }
    .nav-links .btn-login {
      color: var(--primary-dark);
      font-weight: 600;
    }

    /* ===== HERO ===== */
    .hero {
      text-align: center;
      padding: 80px 24px 64px;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      left: 50%;
      transform: translateX(-50%);
      width: 800px;
      height: 800px;
      background: radial-gradient(circle, rgba(108,92,231,0.06) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero h1 {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      max-width: 700px;
      margin: 0 auto 20px;
      position: relative;
    }
    .hero .subtitle {
      font-size: clamp(16px, 2vw, 19px);
      color: var(--text-secondary);
      max-width: 520px;
      margin: 0 auto 36px;
      line-height: 1.5;
    }
    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }
    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      background: var(--accent);
      color: white;
      border: none;
      border-radius: var(--radius-pill);
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition);
      text-decoration: none;
    }
    .btn-primary:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
      box-shadow: 0 4px 16px rgba(108,92,231,0.3);
    }
    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      background: transparent;
      color: var(--primary-dark);
      border: 1.5px solid var(--border-color);
      border-radius: var(--radius-pill);
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition);
      text-decoration: none;
    }
    .btn-secondary:hover {
      border-color: var(--primary-dark);
      background: var(--surface-gray);
    }

    /* ===== TRUSTED BY / LOGO MARQUEE ===== */
    .trusted-by {
      padding: 48px 0 56px;
      text-align: center;
      border-top: 1px solid var(--border-color);
    }
    .trusted-by-label {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-tertiary);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 28px;
    }
    .logo-marquee-wrapper {
      overflow: hidden;
      position: relative;
      mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
      -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
    }
    .logo-marquee {
      display: flex;
      gap: 56px;
      animation: marquee-scroll 30s linear infinite;
      width: max-content;
    }
    .logo-marquee .brand-item {
      font-size: 16px;
      font-weight: 700;
      color: var(--text-tertiary);
      white-space: nowrap;
      flex-shrink: 0;
      opacity: 0.5;
      transition: opacity var(--transition);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .logo-marquee .brand-item:hover { opacity: 0.8; }

    @keyframes marquee-scroll {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }

    /* ===== STATS ===== */
    .stats-section {
      padding: 80px 0;
      background: var(--surface-gray);
    }
    .stats-label {
      text-align: center;
      font-size: 15px;
      color: var(--text-secondary);
      margin-bottom: 40px;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      max-width: 800px;
      margin: 0 auto;
    }
    .stat-card {
      text-align: center;
      padding: 32px 16px;
      background: var(--bg-white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--border-color);
    }
    .stat-number {
      font-size: clamp(36px, 4vw, 52px);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--primary-dark);
      line-height: 1;
      margin-bottom: 8px;
    }
    .stat-label {
      font-size: 14px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    /* ===== FEATURES: SEARCH ===== */
    .features-search {
      padding: 96px 0;
    }
    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }
    .section-header h2 {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 800;
      letter-spacing: -0.02em;
      margin-bottom: 12px;
    }
    .section-header p {
      font-size: 17px;
      color: var(--text-secondary);
      max-width: 520px;
      margin: 0 auto;
    }

    /* Tabs */
    .search-tabs {
      display: flex;
      justify-content: center;
      gap: 4px;
      background: var(--surface-gray);
      border-radius: var(--radius-pill);
      padding: 4px;
      margin-bottom: 24px;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }
    .search-tabs::-webkit-scrollbar { display: none; }
    .search-tab {
      padding: 10px 20px;
      border-radius: var(--radius-pill);
      border: none;
      background: transparent;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition);
      white-space: nowrap;
      font-family: inherit;
    }
    .search-tab.active {
      background: var(--bg-white);
      color: var(--primary-dark);
      box-shadow: var(--shadow-sm);
      font-weight: 600;
    }
    .search-tab:hover:not(.active) { color: var(--primary-dark); }

    /* Filter Pills */
    .filter-pills {
      display: flex;
      gap: 8px;
      justify-content: center;
      flex-wrap: wrap;
      margin-bottom: 36px;
      padding: 0 16px;
    }
    .filter-pill {
      padding: 8px 18px;
      border-radius: var(--radius-pill);
      border: 1.5px solid var(--border-color);
      background: var(--bg-white);
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
    }
    .filter-pill.active {
      background: var(--accent);
      color: white;
      border-color: var(--accent);
    }
    .filter-pill:hover:not(.active) {
      border-color: var(--accent);
      color: var(--accent);
    }

    /* Screenshot Grid */
    .screenshot-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .screenshot-card {
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--surface-gray);
      aspect-ratio: 9/16;
      position: relative;
      transition: all var(--transition);
      border: 1px solid var(--border-color);
    }
    .screenshot-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }
    .screenshot-card .placeholder-screen {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      padding: 16px;
      position: relative;
    }
    .placeholder-screen .status-bar {
      display: flex;
      justify-content: space-between;
      font-size: 10px;
      color: var(--text-tertiary);
      margin-bottom: 16px;
    }
    .placeholder-screen .screen-header {
      height: 14px;
      background: var(--border-color);
      border-radius: 4px;
      margin-bottom: 12px;
      width: 60%;
    }
    .placeholder-screen .screen-content {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .placeholder-screen .screen-line {
      height: 8px;
      background: var(--border-color);
      border-radius: 3px;
    }
    .placeholder-screen .screen-line:nth-child(1) { width: 90%; }
    .placeholder-screen .screen-line:nth-child(2) { width: 75%; }
    .placeholder-screen .screen-line:nth-child(3) { width: 85%; }
    .placeholder-screen .screen-line:nth-child(4) { width: 65%; }
    .placeholder-screen .screen-block {
      height: 60px;
      background: var(--border-color);
      border-radius: var(--radius-sm);
      margin: 8px 0;
    }
    .placeholder-screen .screen-circle {
      width: 36px;
      height: 36px;
      background: var(--border-color);
      border-radius: 50%;
    }
    .placeholder-screen .screen-btn {
      height: 32px;
      background: var(--accent);
      opacity: 0.2;
      border-radius: var(--radius-pill);
      margin-top: auto;
    }
    .screenshot-card .app-label {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 12px 16px;
      background: linear-gradient(transparent, rgba(0,0,0,0.7));
      color: white;
      font-size: 12px;
      font-weight: 600;
    }
    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* ===== FEATURES: FLOWS ===== */
    .features-flows {
      padding: 96px 0;
      background: var(--surface-gray);
    }
    .flows-toggle {
      display: flex;
      justify-content: center;
      gap: 4px;
      background: var(--bg-white);
      border-radius: var(--radius-pill);
      padding: 4px;
      margin-bottom: 40px;
      max-width: 360px;
      margin-left: auto;
      margin-right: auto;
      border: 1px solid var(--border-color);
    }
    .flows-toggle-btn {
      padding: 10px 24px;
      border-radius: var(--radius-pill);
      border: none;
      background: transparent;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
      flex: 1;
      text-align: center;
    }
    .flows-toggle-btn.active {
      background: var(--accent);
      color: white;
      font-weight: 600;
    }
    .flows-content {
      background: var(--bg-white);
      border-radius: var(--radius);
      padding: 40px;
      border: 1px solid var(--border-color);
      box-shadow: var(--shadow-sm);
      max-width: 900px;
      margin: 0 auto;
    }
    .flow-view { display: none; }
    .flow-view.active { display: block; }
    .flow-steps {
      display: flex;
      gap: 16px;
      overflow-x: auto;
      padding-bottom: 8px;
    }
    .flow-step {
      min-width: 160px;
      aspect-ratio: 9/16;
      background: var(--surface-gray);
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-color);
      position: relative;
      flex-shrink: 0;
    }
    .flow-step::after {
      content: '';
      position: absolute;
      right: -12px;
      top: 50%;
      transform: translateY(-50%);
      width: 8px;
      height: 8px;
      border-right: 2px solid var(--accent);
      border-bottom: 2px solid var(--accent);
      transform: translateY(-50%) rotate(-45deg);
    }
    .flow-step:last-child::after { display: none; }
    .flow-video-placeholder {
      aspect-ratio: 16/9;
      background: var(--surface-gray);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--border-color);
    }
    .play-icon {
      width: 64px;
      height: 64px;
      background: var(--accent);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 20px rgba(108,92,231,0.3);
      transition: transform var(--transition);
    }
    .play-icon:hover { transform: scale(1.08); }
    .play-icon svg {
      width: 24px;
      height: 24px;
      fill: white;
      margin-left: 3px;
    }

    /* ===== FEATURES: TOOLS ===== */
    .features-tools {
      padding: 96px 0;
    }
    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .tool-card {
      padding: 32px;
      border-radius: var(--radius);
      border: 1px solid var(--border-color);
      transition: all var(--transition);
      background: var(--bg-white);
    }
    .tool-card:hover {
      border-color: var(--accent);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }
    .tool-icon {
      width: 48px;
      height: 48px;
      background: var(--accent-light);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }
    .tool-icon svg {
      width: 24px;
      height: 24px;
      color: var(--accent);
    }
    .tool-card h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 8px;
      letter-spacing: -0.01em;
    }
    .tool-card p {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials-section {
      padding: 96px 0;
      background: var(--surface-gray);
      overflow: hidden;
    }
    .testimonial-marquee-row {
      display: flex;
      gap: 20px;
      margin-bottom: 20px;
      width: max-content;
    }
    .testimonial-marquee-row:nth-child(1) .testimonial-track {
      animation: testimonial-scroll-left 40s linear infinite;
    }
    .testimonial-marquee-row:nth-child(2) .testimonial-track {
      animation: testimonial-scroll-right 45s linear infinite;
    }
    .testimonial-track {
      display: flex;
      gap: 20px;
    }
    .testimonial-card {
      background: var(--bg-white);
      border-radius: var(--radius);
      padding: 28px;
      border: 1px solid var(--border-color);
      min-width: 380px;
      max-width: 420px;
      flex-shrink: 0;
      transition: box-shadow var(--transition);
    }
    .testimonial-card:hover { box-shadow: var(--shadow-md); }
    .testimonial-text {
      font-size: 14px;
      line-height: 1.7;
      color: var(--primary-dark);
      margin-bottom: 20px;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .testimonial-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--accent-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      font-weight: 700;
      color: var(--accent);
      flex-shrink: 0;
    }
    .testimonial-name {
      font-size: 14px;
      font-weight: 600;
      color: var(--primary-dark);
    }
    .testimonial-company {
      font-size: 12px;
      color: var(--text-tertiary);
    }

    @keyframes testimonial-scroll-left {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }
    @keyframes testimonial-scroll-right {
      from { transform: translateX(-50%); }
      to { transform: translateX(0); }
    }

    /* ===== CTA SECTION ===== */
    .cta-section {
      padding: 96px 0 0;
      text-align: center;
      overflow: hidden;
    }
    .cta-section h2 {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 800;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
    }
    .cta-section .cta-desc {
      font-size: 17px;
      color: var(--text-secondary);
      max-width: 520px;
      margin: 0 auto 36px;
    }
    .cta-buttons {
      display: flex;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 64px;
    }

    /* App Icon Marquee */
    .app-icon-marquee-wrapper {
      padding: 32px 0;
      mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
      -webkit-mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
    }
    .app-icon-row {
      display: flex;
      gap: 20px;
      margin-bottom: 20px;
      width: max-content;
    }
    .app-icon-track {
      display: flex;
      gap: 20px;
    }
    .app-icon-row:nth-child(odd) .app-icon-track {
      animation: marquee-scroll 35s linear infinite;
    }
    .app-icon-row:nth-child(even) .app-icon-track {
      animation: marquee-scroll-reverse 38s linear infinite;
    }
    @keyframes marquee-scroll-reverse {
      from { transform: translateX(-50%); }
      to { transform: translateX(0); }
    }
    .app-icon {
      width: 56px;
      height: 56px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: white;
      flex-shrink: 0;
      box-shadow: var(--shadow-sm);
    }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--primary-dark);
      color: white;
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 48px;
    }
    .footer-brand {
      font-size: 20px;
      font-weight: 800;
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .footer-tagline {
      font-size: 14px;
      color: #9CA3AF;
      line-height: 1.6;
      max-width: 280px;
    }
    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: #9CA3AF;
      margin-bottom: 16px;
    }
    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .footer-col a {
      color: #D1D5DB;
      text-decoration: none;
      font-size: 14px;
      transition: color var(--transition);
    }
    .footer-col a:hover { color: white; }
    .footer-bottom {
      border-top: 1px solid #374151;
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
      font-size: 13px;
      color: #6B7280;
    }
    .footer-bottom a {
      color: #6B7280;
      text-decoration: none;
      transition: color var(--transition);
    }
    .footer-bottom a:hover { color: #D1D5DB; }
    .footer-legal {
      display: flex;
      gap: 24px;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .screenshot-grid { grid-template-columns: repeat(3, 1fr); }
